{
  "findings": [
    {
      "check_id": "CKV2_AWS_6",
      "title": "S3 bucket lacks a Public Access Block",
      "resource": "aws_s3_bucket.bucket_2",
      "severity": "MEDIUM",
      "explanation": "The bucket has no account-independent controls preventing public ACLs or bucket policies. Because its ACL is variable-driven, it could otherwise be configured for public access."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "S3 bucket versioning is not enabled",
      "resource": "aws_s3_bucket.bucket_2",
      "severity": "HIGH",
      "explanation": "The bucket does not enable versioning, leaving stored objects less resilient to accidental deletion, overwrite, or malicious modification."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "S3 access logging is not enabled",
      "resource": "aws_s3_bucket.bucket_2",
      "severity": "HIGH",
      "explanation": "The bucket does not deliver server access logs, reducing the ability to investigate object access and suspicious requests."
    },
    {
      "check_id": "CKV_AWS_144",
      "title": "S3 cross-region replication is not enabled",
      "resource": "aws_s3_bucket.bucket_2",
      "severity": "MEDIUM",
      "explanation": "The bucket has no replication configuration, so its KMS-encrypted objects are not protected against a regional disruption."
    },
    {
      "check_id": "CKV2_AWS_61",
      "title": "S3 bucket lacks a lifecycle configuration",
      "resource": "aws_s3_bucket.bucket_2",
      "severity": "MEDIUM",
      "explanation": "The bucket has no lifecycle rule to clean up abandoned multipart uploads, which can leave unmanaged partial data and ongoing storage costs."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "bucket_2" {
  bucket = "roger-bucket-2"
  acl    = var.bucket_acl

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        kms_master_key_id = aws_kms_key.my_key.arn
        sse_algorithm     = "aws:kms"
      }
    }
  }
}

resource "aws_s3_bucket_public_access_block" "bucket_2" {
  bucket = aws_s3_bucket.bucket_2.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "bucket_2" {
  bucket = aws_s3_bucket.bucket_2.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_logging" "bucket_2" {
  bucket        = aws_s3_bucket.bucket_2.id
  target_bucket = var.access_log_bucket_id
  target_prefix = "s3-access-logs/${aws_s3_bucket.bucket_2.id}/"
}

resource "aws_s3_bucket_lifecycle_configuration" "bucket_2" {
  bucket = aws_s3_bucket.bucket_2.id

  rule {
    id     = "abort-incomplete-multipart-uploads"
    status = "Enabled"

    filter {}

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }
}

resource "aws_s3_bucket_replication_configuration" "bucket_2" {
  depends_on = [aws_s3_bucket_versioning.bucket_2]

  bucket = aws_s3_bucket.bucket_2.id
  role   = var.replication_role_arn

  rule {
    id     = "cross-region-replication"
    status = "Enabled"

    filter {}

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = var.replication_destination_bucket_arn
      storage_class = "STANDARD"

